head.script:
	scwin.onpageload = function() {
		var rowJSON = {
			"Personal Info" : {
				"Name" : "Lee",
				"Age" : 50,
				"Married" : false
			},
			"Region" : "Seoul",
			"Carrier" : true
		};

		var obj = {
			"title" : "Test",
			"windowId" : "001",
			"frameMode" : "wframe",
			"src" : "WESD_1026_tab_sub.xml",
			"confirmTrueAction" : "newWindow",
			"options" : {
				"fixed" : true
			},
			"dataObject" : {
				"type" : "json",
				"name" : "windowParam",
				"data" : rowJSON
			}
		};

		for (var i = 0; i < 5; i++) {
			obj.title = "test_" + i;
			obj.windowId = i;
			window1.createWindow(obj);
		}
	};

	scwin.onpageunload = function() {

	};

	scwin.trigger1_onclick = function(e) {
		window1.setFocus("test_0");
    };

    scwin.trigger2_onclick = function(e) {
		window1.setFocus(1);
    };

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getJq('#window1_nameLayer_'+$p.id+'window1_subWindow0').hasClass('w2windowContainer_nameLayer w2windowContainer_selectedNameLayer');
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
		WebSquare.wUnit.addCommand('pause', '500');
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "400");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
